window.TEACH_SLIDES['7-18'] = [{"k": "title", "html": "<p class=\"ts-kicker\">ថ្នាក់ទី ៧ · មេរៀនទី ១៨</p><h1>មាឌនិងផ្ទៃក្រឡាខាងនៃសូលីត</h1><p class=\"ts-sub\">៥ ផ្នែក</p><div class=\"ts-obj\"><h3>គោលបំណង</h3><ol class=\"ts-bullets\"><li>ប្រាប់បានពីសញ្ញាណទូទៅនៃសូលីត</li><li>បង្ហាញសូលីតមានរាងធរណីមាត្រងាយៗនិងប្រាប់ពីប្រភេទព្រមទាំងធាតុរបស់វា</li><li>កំណត់សញ្ញាណផ្ទៃក្រឡាខាងនៃសូលីត</li><li>គណនាមាឌនៃសូលីតតាមរូបមន្តមាឌ ។</li></ol></div>", "c": "cover"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. សូលីត</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>ធុងសាំង គ្រាប់ឡុកឡាក់ ប្រអប់ដីស... ឱ្យសញ្ញាណនៃសូលីត ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>នេះជាឧទាហរណ៍ខ្លះៗនៃសូលីត ៖</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>2.1. មាឌប្រលេពីប៉ែតកែង</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>ឧទាហរណ៍</h2><p>គេមានប្រលេពីប៉ែតកែងមួយមានបណ្តោយ 7 ទទឹង 4 និងកម្ពស់ 6 ។</p><p>ផ្ទៃបាតមាន \\(7 \\times 4 = 28\\) ការ៉េឯកតា ។</p><p>គេអាចបែងចែកផ្ទៃបាតនៃប្រលេពីប៉ែតកែងជា 28 ការ៉េឯកតាដែលការ៉េនីមួយៗ មានជ្រុងប្រវែង \\(1~\\text{cm}\\) ។ បើគេដាក់គូបមានទ្រនុង \\(1~\\text{cm}\\) លើការ៉េនីមួយៗ នោះគេបានមួយស្រទាប់មានកម្ពស់ \\(1~\\text{cm}\\) និងមានចំនួនគូបសរុបចំនួន 28 គូបឯកតា ។ ប្រលេពីប៉ែតកែងមាន \\(28 \\times 6 = 168\\) គូបដែលមានទ្រនុង \\(1~\\text{cm}\\) ។</p><p>ដូច្នេះមាឌនៃប្រលេពីប៉ែតកែងគឺ \\(7~\\text{cm} \\times 4~\\text{cm} \\times 6~\\text{cm} = 168~\\text{cm}^3\\) ដែលជាផលគុណនៃរង្វាស់វិមាត្រទាំងបី ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>ជាទូទៅ</h2><p>បើ \\(a, b, h\\) ជារង្វាស់វិមាត្រទាំងបី ហើយ \\(\\mathcal{A}_B\\) ជាផ្ទៃក្រឡាបាត និង \\(V\\) ជាមាឌនៃប្រលេពីប៉ែតកែងនោះ គេបានរូបមន្ត ៖ \\[V = a \\times b \\times h \\quad \\text{ឬ} \\quad V = \\mathcal{A}_B \\times h\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>លំហាត់គំរូ 1</h2><p>រកមាឌហិបឈើមួយមានវិមាត្រ \\(45~\\text{dm}\\), \\(24~\\text{dm}\\), \\(12~\\text{dm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>ដំណោះស្រាយ</h2><p>មាឌហិបឈើ ៖ \\[\\begin{aligned}\nV &amp;= 45~\\text{dm} \\times 24~\\text{dm} \\times 12~\\text{dm} \\\\\n  &amp;= 12~960~\\text{dm}^3\n\\end{aligned}\\] ដូចនេះ មាឌហិបឈើគឺ \\(V = 12~960~\\text{dm}^3\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>លំហាត់គំរូ 2</h2><p>ប្រលេពីប៉ែតកែងមួយមានមាឌ \\(83~880~\\text{dm}^3\\) និងកម្ពស់ \\(3.60~\\text{m}\\) ។ រកផ្ទៃក្រឡាបាតប្រលេពីប៉ែតកែង ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>ដំណោះស្រាយ</h2><p>គេមាន \\(V = 83~880~\\text{dm}^3\\) និង \\(h = 3.60~\\text{m} = 36~\\text{dm}\\) ។ ផ្ទៃក្រឡាបាត ៖ \\[\\begin{aligned}\n\\mathcal{A}_B &amp;= \\frac{V}{h} \\\\\n  &amp;= \\frac{83~880~\\text{dm}^3}{36~\\text{dm}} \\\\\n  &amp;= 2~330~\\text{dm}^2\n\\end{aligned}\\] ដូចនេះ \\(\\mathcal{A}_B = 2~330~\\text{dm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>ប្រតិបត្តិ</h2><p>ប្រលេពីប៉ែតកែងមួយមានមាឌ \\(100~352~\\text{dm}^3\\) និងផ្ទៃក្រឡាបាត \\(35~840~\\text{dm}^2\\) ។ រកកម្ពស់ប្រលេពីប៉ែតកែងគិតជាម៉ែត្រ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.1. មាឌប្រលេពីប៉ែតកែង</p><h2>ចម្លើយ</h2><p>កម្ពស់ប្រលេពីប៉ែតកែង ៖ \\[\\begin{aligned}\nh &amp;= \\frac{V}{\\mathcal{A}_B} \\\\\n  &amp;= \\frac{100~352}{35~840} \\\\\n  &amp;= 2.8~\\text{dm} = 0.28~\\text{m}\n\\end{aligned}\\] ដូចនេះ កម្ពស់ប្រលេពីប៉ែតកែងគឺ \\(0.28~\\text{m}\\) (សៀវភៅពុម្ពសរសេរ \\(2.8~\\text{dm}\\)) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>2.2. មាឌគូប</h1>"}, {"k": "", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h2>2.2. មាឌគូប</h2><p>គូប គឺជាប្រលេពីប៉ែតកែងដែលវិមាត្រទាំងបីមានប្រវែងស្មើៗគ្នា ។ ខ្នាតមាឌ គឺម៉ែត្រគូប (\\(\\text{m}^3\\)) ។ មួយម៉ែត្រគូប គឺជាគូបមានទ្រនុងប្រវែងស្មើនឹង \\(1~\\text{m}\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2.2. មាឌគូប</p><h2>ជាទូទៅ</h2><ol class=\"ts-bullets\"><li>បើ \\(V\\) ជាមាឌ ហើយ \\(a\\) ជាទ្រនុងនៃគូបនោះ គេបានរូបមន្ត ៖ \\[V = a \\times a \\times a = a^3\\]</li><li>មាឌនៃគូបស្មើនឹងស្វ័យគុណបីនៃទ្រនុងរបស់វា ៖ \\[V = a^3\\]</li><li>ប្រវែងទ្រនុងគូបស្មើនឹងឫសគូបនៃមាឌរបស់វា ៖ \\[a = \\sqrt[3]{V}\\]</li></ol>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.2. មាឌគូប</p><h2>លំហាត់គំរូ</h2><p>គូបមួយមានវិមាត្រ \\(2.5~\\text{dam}\\) ។ រកមាឌនៃគូបនេះ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.2. មាឌគូប</p><h2>ដំណោះស្រាយ</h2><p>មាឌគូប ៖ \\[\\begin{aligned}\nV &amp;= 2.5 \\times 2.5 \\times 2.5 \\\\\n  &amp;= 15.625~\\text{dam}^3\n\\end{aligned}\\] ដូចនេះ \\(V = 15.625~\\text{dam}^3\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.2. មាឌគូប</p><h2>ប្រតិបត្តិ</h2><p>បូណានិងចន្ទបានយកសាប៊ូដែលមានរាងគូបមកបំពេញក្នុងឡាំងឈើមួយ ទៅតាមវិមាត្រនីមួយៗនៃឡាំងឈើអាចដាក់បានសាប៊ូ 6 ដុំ ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តើឡាំងឈើនោះមានរាងអ្វី?</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>រកមាឌឡាំងឈើដោយយកដុំសាប៊ូជាឯកតាមាឌ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.2. មាឌគូប</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ដោយវិមាត្រទាំងបី (បណ្តោយ ទទឹង កម្ពស់) ដាក់បានសាប៊ូ 6 ដុំស្មើៗគ្នា នោះឡាំងឈើមានរាងជាគូប (ឬប្រលេពីប៉ែតកែងពិសេស) ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>មាឌឡាំងឈើគិតជាដុំសាប៊ូ ៖ \\[\\begin{aligned}\n    V &amp;= 6 \\times 6 \\times 6 \\\\\n      &amp;= 216~\\text{ដុំសាប៊ូ}\n    \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ក. ប្រលេពីប៉ែតកែង (ឬគូប) &emsp; ខ. 216 ដុំសាប៊ូ (សៀវភៅពុម្ពសរសេរ 6) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>2.3. មាឌស៊ីឡាំង</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>ឧទាហរណ៍</h2><p>គេមានព្រីសត្រង់មួយមានបាតជាពហុកោណនិយ័ត ចារឹកក្នុងបាតរង្វង់នៃស៊ីឡាំង ។ បើគេបង្កើនចំនួនជ្រុងនៃបាតព្រីសឱ្យកាន់តែច្រើននោះផ្ទៃបាតនៃព្រីសខិតទៅរកផ្ទៃបាតនៃស៊ីឡាំងហើយព្រីសខិតទៅរកស៊ីឡាំងដែរ ។ គេសន្មតថា មាឌរបស់ស៊ីឡាំងស្មើនឹងផ្ទៃក្រឡាបាតគុណនឹងកម្ពស់ ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>ជាទូទៅ</h2><p>បើ \\(h\\) ជារង្វាស់កម្ពស់ ហើយ \\(\\mathcal{A}_B\\) ជាផ្ទៃក្រឡាបាត និង \\(V\\) ជាមាឌនៃស៊ីឡាំងនោះ គេបាន ៖ \\[V = \\mathcal{A}_B h\\] តែ \\(\\mathcal{A}_B = \\pi R^2\\) នាំឱ្យគេបានរូបមន្តមាឌស៊ីឡាំង ៖ \\[V = \\pi R^2 h\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>លំហាត់គំរូ 1</h2><p>ដែកមួយកំណាត់មានរាងស៊ីឡាំងត្រង់មានប្រវែង \\(8~\\text{m}\\) ។ អង្កត់ផ្ចិតនៃមុខកាត់ស្មើនឹង \\(30~\\text{mm}\\) ។ គណនាមាឌដែកគិតជា \\(\\text{dm}^3\\) ។ (\\(\\pi \\approx 3.14\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>ដំណោះស្រាយ</h2><p>កាំនៃមុខកាត់ ៖ \\[R = \\frac{30}{2} = 15~\\text{mm}\\] ផ្ទៃក្រឡាបាត ៖ \\[\\begin{aligned}\n\\mathcal{A}_B &amp;= \\pi R^2 \\\\\n  &amp;= 3.14 \\times 15^2 \\\\\n  &amp;= 706.5~\\text{mm}^2\n\\end{aligned}\\] កម្ពស់ដែក \\(h = 8~\\text{m} = 8~000~\\text{mm}\\) ។ មាឌដែក ៖ \\[\\begin{aligned}\nV &amp;= \\mathcal{A}_B \\times h \\\\\n  &amp;= 706.5 \\times 8~000 \\\\\n  &amp;= 5~652~000~\\text{mm}^3\n\\end{aligned}\\] ដោយ \\(5~652~000~\\text{mm}^3 = 5.652~\\text{dm}^3\\) ។ ដូចនេះ \\(V = 5.652~\\text{dm}^3\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>លំហាត់គំរូ 2</h2><p>រកមាឌនៃប្រអប់សំបុត្រតាមរូបខាងក្រោម ។ \\(\\left(\\pi \\approx \\dfrac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>ដំណោះស្រាយ</h2><p>មាឌប្រអប់សំបុត្រ ៖ \\[V = V_1 + V_2\\] ដែល \\(V_1\\) ជាមាឌប្រអប់សំបុត្រគ្មានគម្រប និង \\(V_2\\) ជាមាឌគម្របប្រអប់ ។ \\[\\begin{aligned}\nV_1 &amp;= 4 \\times 6 \\times 12 \\\\\n  &amp;= 288~\\text{cm}^3\n\\end{aligned}\\] គម្របប្រអប់ជារាងកន្លះស៊ីឡាំងមានកាំ \\(R = \\dfrac{4}{2} = 2~\\text{cm}\\) និងបណ្តោយ \\(h = 12~\\text{cm}\\) ៖ \\[\\begin{aligned}\nV_2 &amp;= \\frac{1}{2} \\left[ \\frac{22}{7} \\times 2^2 \\times 12 \\right] \\\\\n  &amp;= \\frac{1}{2} \\times \\frac{1~056}{7} \\\\\n  &amp;\\approx 75.428~\\text{cm}^3\n\\end{aligned}\\] \\[\\begin{aligned}\nV &amp;= 288 + 75.428 \\\\\n  &amp;= 363.428~\\text{cm}^3\n\\end{aligned}\\] ដូចនេះ \\(V = 363.428~\\text{cm}^3\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>ប្រតិបត្តិ</h2><p>សុខាធ្វើបំពង់មួយដោយប្រើក្រដាសកាតុងរាងចតុកោណកែងមានបណ្តោយ \\(96.2~\\text{dm}\\) និងទទឹង \\(64.8~\\text{dm}\\) ហើយបិទមុខវាផ្ចិតជាប់គ្នា \\(2~\\text{dm}\\) ។ តើសុខាត្រូវមូរតាមបណ្តោយឬតាមទទឹងដើម្បីឱ្យបានមាឌបំពង់ធំបំផុត ?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2.3. មាឌស៊ីឡាំង</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>បើមូរតាមបណ្តោយ ៖ បរិមាត្របាតគឺ \\(p = 96.2 - 2 = 94.2~\\text{dm}\\) និងកម្ពស់ \\(h = 64.8~\\text{dm}\\) ។ កាំរង្វង់បាត ៖ \\[R = \\frac{94.2}{2 \\times 3.14} = 15~\\text{dm}\\] មាឌបំពង់ ៖ \\[\\begin{aligned}\n    V_1 &amp;= \\pi R^2 h \\\\\n      &amp;= 3.14 \\times 15^2 \\times 64.8 \\\\\n      &amp;= 45~781.2~\\text{dm}^3\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>បើមូរតាមទទឹង ៖ បរិមាត្របាតគឺ \\(p = 64.8 - 2 = 62.8~\\text{dm}\\) និងកម្ពស់ \\(h = 96.2~\\text{dm}\\) ។ កាំរង្វង់បាត ៖ \\[R = \\frac{62.8}{2 \\times 3.14} = 10~\\text{dm}\\] មាឌបំពង់ ៖ \\[\\begin{aligned}\n    V_2 &amp;= \\pi R^2 h \\\\\n      &amp;= 3.14 \\times 10^2 \\times 96.2 \\\\\n      &amp;= 30~206.8~\\text{dm}^3\n    \\end{aligned}\\]</div></li></ul><p>ដោយ \\(45~781.2~\\text{dm}^3 &gt; 30~206.8~\\text{dm}^3\\) ដូចនេះសុខាត្រូវមូរតាមបណ្តោយ ដែលបានមាឌ \\(V = 45~781.2~\\text{dm}^3\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>ឧទាហរណ៍</h2><p>គេមានប្រលេពីប៉ែតកែងមួយមានទ្រនុង \\(a, b, c\\) ធ្វើពីក្រដាស ។ បើគេកាត់ប្រលេពីប៉ែតកែងតាមទ្រនុង និងតាមជុំវិញបាតទាំងពីរ រួចលាតសន្ធឹងវានៅលើប្លង់មួយ នោះគេបានផ្ទៃមួយផ្សំដោយបាតទាំងពីរនៃប្រលេពីប៉ែតកែងនិងផ្នែកមួយទៀតរាងចតុកោណកែងមួយមានបណ្តោយស្មើនឹងបរិមាត្រនៃបាត \\(p\\) និងទទឹងស្មើនឹងកម្ពស់ \\(h\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>ជាទូទៅ</h2><ol class=\"ts-bullets\"><li>ផ្ទៃក្រឡាខាងនៃប្រលេពីប៉ែតកែង ៖ \\[\\mathcal{A}_L = p \\times h = 2(a+b) \\times h\\]</li><li>ផ្ទៃក្រឡាទាំងអស់នៃប្រលេពីប៉ែតកែង ៖ \\[\\mathcal{A}_T = 2\\mathcal{A}_B + \\mathcal{A}_L\\]</li></ol>"}, {"k": "key", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>សម្គាល់</h2><p>បើព្រីសត្រង់មានបាតជាចតុកោណកែង នោះគេហៅថា ប្រលេពីប៉ែតកែង ។ បើមុខទាំង 6 នៃប្រលេពីប៉ែតកែងជាការ៉េប៉ុនគ្នា នោះគេហៅថា គូប ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>ជាទូទៅ</h2><ol class=\"ts-bullets\"><li>ផ្ទៃក្រឡាខាងនៃគូប ៖ \\[\\mathcal{A}_L = p \\times h = 4a \\times a = 4a^2\\]</li><li>ផ្ទៃក្រឡាទាំងអស់នៃគូប ៖ \\[\\mathcal{A}_T = 4a^2 + 2a^2 = 6a^2\\]</li></ol>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>លំហាត់គំរូ</h2><p>គណនាផ្ទៃក្រឡាខាងទាំងអស់នៃដុំសាប៊ូតាមរូបខាងស្តាំ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>ដំណោះស្រាយ</h2><p>ដោយដុំសាប៊ូរាងជាប្រលេពីប៉ែតកែងមានបាតជាការ៉េមានជ្រុង \\(a = 4~\\text{cm}\\) និងកម្ពស់ \\(h = 18~\\text{cm}\\) ៖ ផ្ទៃក្រឡាខាង ៖ \\[\\begin{aligned}\n\\mathcal{A}_L &amp;= p \\times h \\\\\n  &amp;= 4 \\times 4 \\times 18 \\\\\n  &amp;= 288~\\text{cm}^2\n\\end{aligned}\\] ផ្ទៃក្រឡាបាត ៖ \\[\\mathcal{A}_B = 4^2 = 16~\\text{cm}^2\\] ផ្ទៃក្រឡាទាំងអស់ ៖ \\[\\begin{aligned}\n\\mathcal{A}_T &amp;= \\mathcal{A}_L + 2\\mathcal{A}_B \\\\\n  &amp;= 288 + 2 \\times 16 \\\\\n  &amp;= 288 + 32 \\\\\n  &amp;= 320~\\text{cm}^2\n\\end{aligned}\\] ដូចនេះ \\(\\mathcal{A}_T = 320~\\text{cm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>ប្រតិបត្តិ</h2><p>គណនាផ្ទៃក្រឡាខាងទាំងអស់នៃគូបដែលមានទ្រនុង \\(184~\\text{mm}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3.1. ផ្ទៃក្រឡាខាងប្រលេពីប៉ែតកែងនិងគូប</p><h2>ចម្លើយ</h2><p>ផ្ទៃក្រឡាទាំងអស់នៃគូប ៖ \\[\\begin{aligned}\n\\mathcal{A}_T &amp;= 6a^2 \\\\\n  &amp;= 6 \\times (184)^2 \\\\\n  &amp;= 6 \\times 33~856 \\\\\n  &amp;= 203~136~\\text{mm}^2\n\\end{aligned}\\] ដូចនេះ \\(\\mathcal{A}_T = 203~136~\\text{mm}^2\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>ឧទាហរណ៍</h2><p>បើគេវះពន្លាតកំប៉ុងមួយមានរាងស៊ីឡាំងមកដាក់នៅលើប្លង់មួយ នោះគេបានចតុកោណកែងមួយ និងរង្វង់ពីរដែលមានបណ្តោយជាបរិមាត្រនៃថាសបាត និងទទឹងរបស់វាជាកម្ពស់នៃស៊ីឡាំង ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>ជាទូទៅ</h2><ol class=\"ts-bullets\"><li>ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង = បរិមាត្ររង្វង់បាត \\(\\times\\) កម្ពស់ \\[\\mathcal{A}_L = p \\times h = 2\\pi Rh\\]</li><li>ផ្ទៃក្រឡាទាំងអស់នៃស៊ីឡាំង = ផ្ទៃក្រឡាខាង + \\(2 \\times\\) ផ្ទៃក្រឡាបាត \\[\\mathcal{A}_T = 2\\pi Rh + 2\\pi R^2\\]</li></ol>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>លំហាត់គំរូ 1</h2><p>គណនាផ្ទៃក្រឡាខាងបំពង់ទឹកដែល \\(D = 0.8~\\text{m}\\), \\(h = 17~\\text{m}\\) ។ \\(\\left(\\pi \\approx \\dfrac{22}{7}\\right)\\)</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>ដំណោះស្រាយ</h2><p>កាំបំពង់ទឹក ៖ \\[R = \\frac{D}{2} = \\frac{0.8}{2} = 0.4~\\text{m}\\] ផ្ទៃក្រឡាខាងបំពង់ទឹក ៖ \\[\\begin{aligned}\n\\mathcal{A}_L &amp;= 2\\pi Rh \\\\\n  &amp;= 2 \\times \\frac{22}{7} \\times 0.4 \\times 17 \\\\\n  &amp;= \\frac{299.2}{7} \\\\\n  &amp;\\approx 42.74~\\text{m}^2\n\\end{aligned}\\] ដូចនេះ \\(\\mathcal{A}_L \\approx 42.74~\\text{m}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>លំហាត់គំរូ 2</h2><p>គណនាផ្ទៃក្រឡាទាំងអស់នៃធុងសាំងមួយមាន \\(h = 1.50~\\text{m}\\), \\(R = 0.4~\\text{m}\\) ។ (\\(\\pi \\approx 3.14\\))</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>ដំណោះស្រាយ</h2><p>ផ្ទៃក្រឡាខាង ៖ \\[\\begin{aligned}\n\\mathcal{A}_L &amp;= 2\\pi Rh \\\\\n  &amp;= 2 \\times 3.14 \\times 0.4 \\times 1.50 \\\\\n  &amp;= 3.768~\\text{m}^2\n\\end{aligned}\\] ផ្ទៃក្រឡាបាតទាំងពីរ ៖ \\[\\begin{aligned}\n2\\mathcal{A}_B &amp;= 2\\pi R^2 \\\\\n  &amp;= 2 \\times 3.14 \\times (0.4)^2 \\\\\n  &amp;= 1.0048~\\text{m}^2\n\\end{aligned}\\] ផ្ទៃក្រឡាទាំងអស់ ៖ \\[\\begin{aligned}\n\\mathcal{A}_T &amp;= \\mathcal{A}_L + 2\\mathcal{A}_B \\\\\n  &amp;= 3.768 + 1.0048 \\\\\n  &amp;= 4.7728~\\text{m}^2\n\\end{aligned}\\] ដូចនេះ \\(\\mathcal{A}_T = 4.7728~\\text{m}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>ប្រតិបត្តិ</h2><p>ស៊ីឡាំងមួយមានមាឌ \\(1550.25~\\text{dm}^3\\) និងកម្ពស់ \\(12.5~\\text{dm}\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាផ្ទៃក្រឡាបាត</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គណនាប្រវែងកាំ \\(\\left(\\pi \\approx \\dfrac{22}{7} \\text{ រួចមើលតារាងការ៉េ}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>គណនាផ្ទៃក្រឡាទាំងអស់ ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3.2. ផ្ទៃក្រឡាខាងនៃស៊ីឡាំង</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ផ្ទៃក្រឡាបាត ៖ \\[\\begin{aligned}\n    \\mathcal{A}_B &amp;= \\frac{V}{h} \\\\\n      &amp;= \\frac{1550.25}{12.5} \\\\\n      &amp;= 124.02~\\text{dm}^2\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>កាំនៃរង្វង់បាត ៖ \\[\\begin{aligned}\n    \\mathcal{A}_B &amp;= \\pi R^2 \\\\\n    R^2 &amp;= \\frac{\\mathcal{A}_B}{\\pi} \\\\\n      &amp;= \\frac{124.02}{\\frac{22}{7}} \\\\\n      &amp;= \\frac{124.02 \\times 7}{22} \\\\\n      &amp;= \\frac{868.14}{22} \\approx 39.4609\n    \\end{aligned}\\] គេបាន \\(R = \\sqrt{39.4609} \\approx 6.28~\\text{dm}\\) ។</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ផ្ទៃក្រឡាទាំងអស់ ៖ \\[\\begin{aligned}\n    \\mathcal{A}_T &amp;= 2\\pi Rh + 2\\mathcal{A}_B \\\\\n      &amp;= 2 \\times \\frac{22}{7} \\times 6.28 \\times 12.5 + 2 \\times 124.02 \\\\\n      &amp;= \\frac{3~454}{7} + 248.04 \\\\\n      &amp;\\approx 493.43 + 248.04 \\\\\n      &amp;= 741.47~\\text{dm}^2\n    \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ក. \\(124.02~\\text{dm}^2\\) &emsp; ខ. \\(6.28~\\text{dm}\\) &emsp; គ. \\(741.46~\\text{dm}^2\\) (តាមសៀវភៅពុម្ព \\(741.46~\\text{dm}^2\\)) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ១៨</p><h1>លំហាត់</h1><p class=\"ts-sub\">មាឌនិងផ្ទៃក្រឡាខាងនៃសូលីត</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១</h2><p>រកផ្ទៃក្រឡាទាំងអស់នៃព្រីសនីមួយៗខាងក្រោម ៖</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១ <span class=\"ts-pg\">(១/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គូបមានទ្រនុង \\(a = 5~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        \\mathcal{A}_T &amp;= 6a^2 \\\\\n          &amp;= 6 \\times 5^2 \\\\\n          &amp;= 6 \\times 25 \\\\\n          &amp;= 150~\\text{cm}^2\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ព្រីសរាងអក្សរ C (ខ្នាតគិតជា \\(\\text{m}\\)) ៖ បាតមានផ្ទៃស្មើផ្ទៃចតុកោណកែងធំ \\(7 \\times 10\\) ដកប្រហោង \\((7 - 3.5) \\times (10 - 3 - 3) = 3.5 \\times 4\\) ៖ \\[\\mathcal{A}_B = 7 \\times 10 - 3.5 \\times 4 = 70 - 14 = 56~\\text{m}^2\\] បរិមាត្របាត ៖ \\[p = 10 + 7 + 3 + 3.5 + 4 + 3.5 + 3 + 7 = 41~\\text{m}\\] កម្ពស់ (ជម្រៅព្រីស) \\(h = 4~\\text{m}\\) ៖ \\[\\mathcal{A}_L = p \\times h = 41 \\times 4 = 164~\\text{m}^2\\] \\[\\mathcal{A}_T = 2\\mathcal{A}_B + \\mathcal{A}_L = 2 \\times 56 + 164 = 112 + 164 = 276~\\text{m}^2\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១ <span class=\"ts-pg\">(២/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>ព្រីសរាងអក្សរ T (ខ្នាតគិតជា \\(\\text{cm}\\)) ៖ បាតផ្សំដោយចតុកោណកែងផ្តេក \\(12 \\times 2\\) និងបញ្ឈរ \\(2 \\times 5\\) ៖ \\[\\mathcal{A}_B = 12 \\times 2 + 2 \\times 5 = 24 + 10 = 34~\\text{cm}^2\\] បរិមាត្របាត ៖ \\[p = 12 + 2 + 5 + 5 + 2 + 5 + 5 + 2 = 38~\\text{cm}\\] កម្ពស់ (ជម្រៅព្រីស) \\(h = 5~\\text{cm}\\) ៖ \\[\\mathcal{A}_L = p \\times h = 38 \\times 5 = 190~\\text{cm}^2\\] \\[\\mathcal{A}_T = 2\\mathcal{A}_B + \\mathcal{A}_L = 2 \\times 34 + 190 = 68 + 190 = 258~\\text{cm}^2\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>ព្រីសរាងកាំជណ្តើរ (ខ្នាតគិតជា \\(\\text{dm}\\)) ៖ បាតផ្សំដោយចតុកោណកែងឆ្វេង \\(5 \\times (2 + 4) = 5 \\times 6 = 30~\\text{dm}^2\\) និងស្តាំ \\(7 \\times 2 = 14~\\text{dm}^2\\) ៖ \\[\\mathcal{A}_B = 30 + 14 = 44~\\text{dm}^2\\] បរិមាត្របាត ៖ \\[p = 12 + 2 + 7 + 4 + 5 + 6 = 36~\\text{dm}\\] កម្ពស់ (ជម្រៅព្រីស) \\(h = 8~\\text{dm}\\) ៖ \\[\\mathcal{A}_L = p \\times h = 36 \\times 8 = 288~\\text{dm}^2\\] \\[\\mathcal{A}_T = 2\\mathcal{A}_B + \\mathcal{A}_L = 2 \\times 44 + 288 = 88 + 288 = 376~\\text{dm}^2\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១ <span class=\"ts-pg\">(៣/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ង.</span><div>ប្រលេពីប៉ែតកែងមានវិមាត្រ \\(150~\\text{mm}\\), \\(32.98~\\text{mm}\\), \\(76.3~\\text{mm}\\) ៖ \\[\\begin{aligned}\n        \\mathcal{A}_T &amp;= 2(ab + bh + ah) \\\\\n          &amp;= 2(150 \\times 32.98 + 32.98 \\times 76.3 + 150 \\times 76.3) \\\\\n          &amp;= 2(4~947 + 2~516.374 + 11~445) \\\\\n          &amp;= 2 \\times 18~908.374 \\\\\n          &amp;= 37~816.748~\\text{mm}^2\n        \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ផ្ទៃក្រឡាទាំងអស់នៃព្រីសនីមួយៗគឺ ៖ ក. \\(150~\\text{cm}^2\\) &emsp; ខ. \\(276~\\text{m}^2\\) &emsp; គ. \\(258~\\text{cm}^2\\) &emsp; ឃ. \\(376~\\text{dm}^2\\) &emsp; ង. \\(37~816.748~\\text{mm}^2\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ២</h2><p>រកមាឌនិងផ្ទៃក្រឡាទាំងអស់នៃរូបនីមួយៗខាងក្រោម ៖</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២ <span class=\"ts-pg\">(១/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ស៊ីឡាំងទី 1 ៖ ក្នុងរូបមានអង្កត់ផ្ចិត \\(d = 1~\\text{cm} \\implies R = 0.5~\\text{cm}\\) (សៀវភៅពុម្ពមិនបានដាក់ប្រវែងបណ្តោយ \\(h\\)) ។ បើសន្មត \\(h = 1~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        V &amp;= \\pi R^2 h = 3.14 \\times (0.5)^2 \\times 1 = 0.785~\\text{cm}^3 \\\\\n        \\mathcal{A}_T &amp;= 2\\pi Rh + 2\\pi R^2 = 2 \\times 3.14 \\times 0.5 \\times 1 + 2 \\times 3.14 \\times 0.25 \\\\\n          &amp;= 3.14 + 1.57 = 4.71~\\text{cm}^2\n        \\end{aligned}\\] (ជារួមតាមរូបមន្ត ៖ \\(V = 0.25\\pi h = 0.785h~\\text{cm}^3\\), \\(\\mathcal{A}_T = \\pi h + 0.5\\pi = 3.14h + 1.57~\\text{cm}^2\\)) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២ <span class=\"ts-pg\">(២/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ស៊ីឡាំងទី 2 ៖ ក្នុងរូបមានអង្កត់ផ្ចិត \\(d = 7~\\text{cm} \\implies R = 3.5~\\text{cm}\\) (សៀវភៅពុម្ពមិនបានដាក់ប្រវែងបណ្តោយ \\(h\\)) ។ យក \\(\\pi \\approx \\frac{22}{7}\\) បើសន្មត \\(h = 7~\\text{cm}\\) ៖ \\[\\begin{aligned}\n        V &amp;= \\pi R^2 h = \\frac{22}{7} \\times (3.5)^2 \\times 7 = 22 \\times 12.25 = 269.5~\\text{cm}^3 \\\\\n        \\mathcal{A}_T &amp;= 2\\pi Rh + 2\\pi R^2 = 2 \\times \\frac{22}{7} \\times 3.5 \\times 7 + 2 \\times \\frac{22}{7} \\times 12.25 \\\\\n          &amp;= 154 + 77 = 231~\\text{cm}^2\n        \\end{aligned}\\] (ជារួមតាមរូបមន្ត ៖ \\(V = 38.5h~\\text{cm}^3\\), \\(\\mathcal{A}_T = 22h + 77~\\text{cm}^2\\)) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២ <span class=\"ts-pg\">(៣/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>ស៊ីឡាំងទី 3 ៖ មានកាំ \\(R = 20~\\text{mm}\\) និងកម្ពស់ \\(h = 35~\\text{mm}\\) (\\(\\pi \\approx 3.14\\)) ៖ \\[\\begin{aligned}\n        V &amp;= \\pi R^2 h \\\\\n          &amp;= 3.14 \\times 20^2 \\times 35 \\\\\n          &amp;= 3.14 \\times 400 \\times 35 \\\\\n          &amp;= 43~960~\\text{mm}^3\n        \\end{aligned}\\] \\[\\begin{aligned}\n        \\mathcal{A}_L &amp;= 2\\pi Rh = 2 \\times 3.14 \\times 20 \\times 35 = 4~396~\\text{mm}^2 \\\\\n        \\mathcal{A}_B &amp;= \\pi R^2 = 3.14 \\times 400 = 1~256~\\text{mm}^2 \\\\\n        \\mathcal{A}_T &amp;= \\mathcal{A}_L + 2\\mathcal{A}_B = 4~396 + 2 \\times 1~256 = 4~396 + 2~512 = 6~908~\\text{mm}^2\n        \\end{aligned}\\] (បើ \\(20~\\text{mm}\\) ជាអង្កត់ផ្ចិត នោះ \\(R = 10~\\text{mm}\\) នាំឱ្យ \\(V = 10~990~\\text{mm}^3\\) និង \\(\\mathcal{A}_T = 2~826~\\text{mm}^2\\)) ។</div></li></ul><p>ដូចនេះ ស៊ីឡាំងទី 3 ៖ \\(V = 43~960~\\text{mm}^3\\), \\(\\mathcal{A}_T = 6~908~\\text{mm}^2\\) (សម្រាប់រូបទី 1 និងទី 2 សៀវភៅពុម្ពខ្វះរង្វាស់កម្ពស់ \\(h\\)) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៣</h2><p>ស្ពាន់មួយមានប្រវែង \\(150~\\text{m}\\) មានអង្កត់ផ្ចិត \\(0.6~\\text{cm}\\) ។ រកម៉ាសនៃស្ពាន់នោះ (\\(\\pi \\approx 3.14\\) ហើយស្ពាន់មានម៉ាសមាឌ \\(8.9~\\text{kg/dm}^3\\)) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៣</h2><p>ប្តូរខ្នាតជាដេស៊ីម៉ែត្រ (\\(\\text{dm}\\)) ៖ ប្រវែងស្ពាន់ \\(h = 150~\\text{m} = 1~500~\\text{dm}\\) ។ អង្កត់ផ្ចិត \\(d = 0.6~\\text{cm} = 0.06~\\text{dm} \\implies R = \\frac{0.06}{2} = 0.03~\\text{dm}\\) ។ ផ្ទៃក្រឡាបាត ៖ \\[\\begin{aligned}\n    \\mathcal{A}_B &amp;= \\pi R^2 \\\\\n      &amp;= 3.14 \\times (0.03)^2 \\\\\n      &amp;= 3.14 \\times 0.0009 \\\\\n      &amp;= 0.002826~\\text{dm}^2\n    \\end{aligned}\\] មាឌនៃស្ពាន់ ៖ \\[\\begin{aligned}\n    V &amp;= \\mathcal{A}_B \\times h \\\\\n      &amp;= 0.002826 \\times 1~500 \\\\\n      &amp;= 4.239~\\text{dm}^3\n    \\end{aligned}\\] ម៉ាសនៃស្ពាន់ ៖ \\[\\begin{aligned}\n    m &amp;= V \\times \\rho \\\\\n      &amp;= 4.239~\\text{dm}^3 \\times 8.9~\\text{kg/dm}^3 \\\\\n      &amp;= 37.7271~\\text{kg}\n    \\end{aligned}\\] ដូចនេះ ម៉ាសនៃស្ពាន់គឺ \\(m = 37.7271~\\text{kg}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៤</h2><p>រថយន្តមួយមានធុងសាំងរាងស៊ីឡាំងដែលមានអង្កត់ផ្ចិត \\(68~\\text{cm}\\) និងបណ្តោយ \\(42~\\text{cm}\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>រកចំណុះធុងសាំងរថយន្ត ។ \\(\\left(\\pi \\approx \\dfrac{22}{7}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>បើធុងសាំងនោះមានសាំងពេញ ។ រថយន្តធ្វើដំណើរពីភ្នំពេញឆ្ពោះទៅកាន់ខេត្តព្រះវិហារដែលមានចម្ងាយផ្លូវ \\(294~\\text{km}\\) (តាមផ្លូវជាតិលេខ 64) ហើយស្អែកឡើងត្រលប់មកវិញ ។ តើគេត្រូវទិញសាំងថែមទៀតឬទេ ? ដោយដឹងថារថយន្តនោះស៊ីសាំង \\(8.7~\\text{L}\\) ក្នុង \\(100~\\text{km}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>កាំរង្វង់បាតធុងសាំង \\(R = \\dfrac{68}{2} = 34~\\text{cm}\\) និងកម្ពស់ (បណ្តោយ) \\(h = 42~\\text{cm}\\) ៖ មាឌធុងសាំង ៖ \\[\\begin{aligned}\n        V &amp;= \\pi R^2 h \\\\\n          &amp;= \\frac{22}{7} \\times 34^2 \\times 42 \\\\\n          &amp;= 22 \\times 1~156 \\times 6 \\\\\n          &amp;= 152~592~\\text{cm}^3\n        \\end{aligned}\\] ដោយ \\(1~\\text{L} = 1~000~\\text{cm}^3\\) នាំឱ្យ \\(V = 152.592~\\text{L}\\) ។ ដូចនេះ ចំណុះធុងសាំងរថយន្តគឺ \\(152.592~\\text{L}\\) ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ចម្ងាយផ្លូវទៅមក ៖ \\[s = 294 \\times 2 = 588~\\text{km}\\] បរិមាណសាំងដែលរថយន្តស៊ីសម្រាប់ចម្ងាយ \\(588~\\text{km}\\) ៖ \\[\\begin{aligned}\n        \\text{សាំងប្រើប្រាស់} &amp;= \\frac{588 \\times 8.7}{100} \\\\\n          &amp;= \\frac{5~115.6}{100} \\\\\n          &amp;= 51.156~\\text{L}\n        \\end{aligned}\\] ដោយសាំងពេញធុងមាន \\(152.592~\\text{L} &gt; 51.156~\\text{L}\\) (នៅសល់ \\(152.592 - 51.156 = 101.436~\\text{L}\\)) ។</div></li></ul><p>ដូចនេះ គេមិនបាច់ទិញសាំងថែមទៀតទេ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៥</h2><p>ផ្ទះមួយមានរាងប្រលេពីប៉ែតកែងមានដំបូលជារាងព្រីសត្រង់បន្តុបពីលើ (ដូចរូបខាងស្តាំ) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាមាឌផ្ទះនោះ</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>បើគេប្រក់ក្បឿងផ្ទះនោះ 25 សន្លឹកក្នុង \\(1~\\text{m}^2\\) ហើយបែកអស់ 5% នៅពេលប្រក់ ។ តើគេត្រូវប្រើក្បឿងប៉ុន្មានសន្លឹក ?</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តើគេត្រូវចំណាយអស់ប្រាក់ប៉ុន្មាន បើក្បឿងមួយសន្លឹកថ្លៃ 438.50 រៀល ?</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គេលាបជញ្ជាំងពីខាងក្នុង ខាងក្រៅនិងពិដានដែលដាក់ត្រឹមកម្ពស់ជញ្ជាំង ។ ផ្ទៃក្រឡាទ្វារនិងបង្អួចស្មើនឹង \\(\\dfrac{1}{4}\\) នៃផ្ទៃក្រឡាជញ្ជាំង ។ ថ្នាំលាប \\(350~\\text{g}\\) អាចលាបបាន \\(1~\\text{m}^2\\) ។ តើគេត្រូវចំណាយប្រាក់ប៉ុន្មានរៀល បើថ្នាំលាបមួយកំប៉ុងមានម៉ាស \\(5~\\text{kg}\\) មានតម្លៃ 49 600 រៀល ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(១/៤)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>មាឌផ្ទះផ្សំដោយ ៖ - មាឌប្រលេពីប៉ែតកែង (ផ្នែកខាងក្រោម) ៖ \\[V_1 = 12 \\times 8 \\times 6 = 576~\\text{m}^3\\] - មាឌដំបូលរាងព្រីសត្រីកោណ ៖ កម្ពស់ត្រីកោណដំបូលគឺ \\(9 - 6 = 3~\\text{m}\\) និងបាត \\(8~\\text{m}\\) ៖ \\[\\mathcal{A}_{\\text{បាតព្រីស}} = \\frac{1}{2} \\times 8 \\times 3 = 12~\\text{m}^2\\] \\[V_2 = 12 \\times 12 = 144~\\text{m}^3\\] មាឌផ្ទះសរុប ៖ \\[V = V_1 + V_2 = 576 + 144 = 720~\\text{m}^3\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ផ្ទៃក្រឡាដំបូលដែលត្រូវប្រក់ក្បឿងមាន 2 ផ្ទាំងរាងចតុកោណកែង (បណ្តោយ \\(12~\\text{m}\\) ទទឹងចំណោត \\(5~\\text{m}\\)) ៖ \\[\\mathcal{A}_{\\text{ដំបូល}} = 2 \\times (12 \\times 5) = 120~\\text{m}^2\\] ចំនួនក្បឿងសម្រាប់ផ្ទៃដំបូល ៖ \\[120 \\times 25 = 3~000~\\text{សន្លឹក}\\] ដោយបែកអស់ 5% នៅពេលប្រក់ ៖ - បើគិតក្បឿងបម្រុងទុក 5% លើចំនួន 3000 សន្លឹក ៖ \\[3~000 + 3~000 \\times 5\\% = 3~000 + 150 = 3~150~\\text{សន្លឹក}\\] (បើគិតក្បឿងសរុប \\(N\\) ដែល \\(95\\% N = 3~000\\) នោះ \\(N = \\frac{3~000}{0.95} \\approx 3~158\\) សន្លឹក) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(២/៤)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>ប្រាក់ចំណាយទិញក្បឿង (សម្រាប់ 3 150 សន្លឹក) ៖ \\[\\begin{aligned}\n        \\text{ប្រាក់ទិញក្បឿង} &amp;= 3~150 \\times 438.50 \\\\\n          &amp;= 1~381~275~\\text{រៀល}\n        \\end{aligned}\\] (បើ 3 158 សន្លឹក ៖ \\(3~158 \\times 438.50 = 1~384~583\\) រៀល; បើគិតតែ 3000 សន្លឹក ៖ \\(1~315~500\\) រៀល) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(៣/៤)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គណនាប្រាក់ចំណាយទិញថ្នាំលាប ៖ - ផ្ទៃក្រឡាជញ្ជាំងជុំវិញ (កម្ពស់ \\(6~\\text{m}\\)) ៖ \\[\\mathcal{A}_{\\text{ជញ្ជាំង}} = 2(12 + 8) \\times 6 = 40 \\times 6 = 240~\\text{m}^2\\] - ផ្ទៃទ្វារនិងបង្អួចស្មើនឹង \\(\\frac{1}{4}\\mathcal{A}_{\\text{ជញ្ជាំង}} = \\frac{1}{4} \\times 240 = 60~\\text{m}^2\\) ៖ ផ្ទៃជញ្ជាំងត្រូវលាបមួយជុំ \\(= 240 - 60 = 180~\\text{m}^2\\) ។ លាបទាំងខាងក្នុងនិងខាងក្រៅ ៖ \\[\\mathcal{A}_{\\text{ជញ្ជាំងលាប}} = 180 \\times 2 = 360~\\text{m}^2\\] - ផ្ទៃពិដាន (រាងចតុកោណកែង \\(12~\\text{m} \\times 8~\\text{m}\\)) ៖ \\[\\mathcal{A}_{\\text{ពិដាន}} = 12 \\times 8 = 96~\\text{m}^2\\] ផ្ទៃក្រឡាសរុបត្រូវលាប ៖ \\[\\mathcal{A}_{\\text{សរុប}} = 360 + 96 = 456~\\text{m}^2\\] (ចំណាំ ៖ បើរាប់បញ្ចូលទាំងហោជាងត្រីកោណខាងក្រៅ \\(2 \\times 12 = 24~\\text{m}^2\\) នោះផ្ទៃសរុបគឺ \\(480~\\text{m}^2\\)) ។ - ម៉ាសថ្នាំលាបត្រូវការ (សម្រាប់ \\(456~\\text{m}^2\\)) ៖ \\[456 \\times 350~\\text{g} = 159~600~\\text{g} = 159.6~\\text{kg}\\] - ចំនួនកំប៉ុងថ្នាំលាប (មួយកំប៉ុង \\(5~\\text{kg}\\)) ៖ \\[\\frac{159.6}{5} = 31.92 \\approx 32~\\text{កំប៉ុង}\\] - ប្រាក់ចំណាយទិញថ្នាំលាប (ទិញ 32 កំប៉ុង) ៖ \\[32 \\times 49~600 = 1~587~200~\\text{រៀល}\\] (បើទិញគិតតាមបរិមាណជាក់ស្តែង \\(31.92 \\times 49~600 = 1~583~232\\) រៀល; បើផ្ទៃ \\(480~\\text{m}^2\\) ត្រូវការ \\(168~\\text{kg} \\implies 34\\) កំប៉ុង \\(= 1~686~400\\) រៀល) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥ <span class=\"ts-pg\">(៤/៤)</span></h2><p>ដូចនេះ ក. \\(V = 720~\\text{m}^3\\) &emsp; ខ. \\(3~150\\) សន្លឹក &emsp; គ. \\(1~381~275\\) រៀល &emsp; ឃ. \\(1~587~200\\) រៀល (32 កំប៉ុង) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ១៨</p><h1>ចប់មេរៀន</h1><p class=\"ts-sub\">មាឌនិងផ្ទៃក្រឡាខាងនៃសូលីត</p>"}];
